"""Rotate app.log: move entries older than 7 days before AS_OF to archive.log."""

import sys
from datetime import datetime, timezone


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 86400  # 7 days in seconds

    try:
        with open("app.log", "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("app.log not found", file=sys.stderr)
        sys.exit(1)

    old_entries = []
    keep_entries = []

    for line in lines:
        line_str = line.rstrip("\n")
        if not line_str:
            continue
        # Parse timestamp: first 19 characters are YYYY-MM-DD HH:MM:SS
        ts_str = line_str[:19]
        try:
            dt = datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S")
            dt = dt.replace(tzinfo=timezone.utc)
            entry_ts = int(dt.timestamp())
        except ValueError:
            # If timestamp can't be parsed, keep the line
            keep_entries.append(line_str)
            continue

        if entry_ts < cutoff:
            old_entries.append(line_str)
        else:
            keep_entries.append(line_str)

    # Append old entries to archive.log
    if old_entries:
        with open("archive.log", "a") as f:
            for entry in old_entries:
                f.write(entry + "\n")

    # Rewrite app.log with remaining entries
    with open("app.log", "w") as f:
        for entry in keep_entries:
            f.write(entry + "\n")


if __name__ == "__main__":
    main()

